package com.example.rokidkeyboardbridge;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public final class ContinuousVoiceInputTest {
 static void ok(boolean b,String m){if(!b)throw new AssertionError(m);}
 static void waitFor(java.util.function.BooleanSupplier b)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(!b.getAsBoolean()&&System.nanoTime()<until)Thread.sleep(5);ok(b.getAsBoolean(),"timed out");}
 public static void main(String[]args)throws Exception{
  CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1),ended=new CountDownLatch(1);AtomicInteger captures=new AtomicInteger();List<String> texts=Collections.synchronizedList(new ArrayList<>());AtomicBoolean paused=new AtomicBoolean();
  ContinuousVoiceInput session=new ContinuousVoiceInput(new ContinuousVoiceInput.Source(){public byte[] capture(java.util.function.BooleanSupplier finish){return new byte[]{(byte)captures.incrementAndGet()};}public void stop(){}},pcm->{if(pcm[0]==1){entered.countDown();release.await();}return "segment"+pcm[0];},new ContinuousVoiceInput.Listener(){public void text(String s){texts.add(s);}public void state(String s){if(s.contains("録音休止"))paused.set(true);}public void error(String s){throw new AssertionError(s);}public void ended(){ended.countDown();}},()->true);
  session.start();ok(entered.await(2,TimeUnit.SECONDS),"decoder did not start");waitFor(()->captures.get()==3&&paused.get());ok(texts.isEmpty(),"decoder must still wait");ok(session.hasUnfinishedAudio(),"recognition backlog must block early dispatch");session.finish();release.countDown();ok(ended.await(3,TimeUnit.SECONDS),"finish did not drain");ok(texts.equals(Arrays.asList("segment1","segment2","segment3")),"order/drop: "+texts);ok(captures.get()==3,"backpressure exceeded queue");
  CountDownLatch blocked=new CountDownLatch(1),cancelEnd=new CountDownLatch(1);AtomicInteger delivered=new AtomicInteger();ContinuousVoiceInput cancelled=new ContinuousVoiceInput(new ContinuousVoiceInput.Source(){public byte[] capture(java.util.function.BooleanSupplier f){return new byte[]{1};}public void stop(){}},pcm->{blocked.countDown();Thread.sleep(5000);return "must not deliver";},new ContinuousVoiceInput.Listener(){public void text(String s){delivered.incrementAndGet();}public void state(String s){}public void error(String s){}public void ended(){cancelEnd.countDown();}},()->true);cancelled.start();ok(blocked.await(2,TimeUnit.SECONDS),"cancel setup");cancelled.cancel();ok(cancelEnd.await(2,TimeUnit.SECONDS),"cancel blocked");ok(delivered.get()==0,"stale result delivered");
  AtomicBoolean speaking=new AtomicBoolean(true);CountDownLatch speechEnded=new CountDownLatch(1);ContinuousVoiceInput speechSession=new ContinuousVoiceInput(new ContinuousVoiceInput.Source(){public boolean speaking(){return speaking.get();}public byte[] capture(java.util.function.BooleanSupplier f)throws Exception{while(!f.getAsBoolean())Thread.sleep(10);return null;}public void stop(){}},pcm->"unused",new ContinuousVoiceInput.Listener(){public void text(String s){throw new AssertionError("unexpected text");}public void state(String s){}public void error(String s){throw new AssertionError(s);}public void ended(){speechEnded.countDown();}},()->true);speechSession.start();ok(speechSession.hasUnfinishedAudio(),"live speech must defer dispatch even without queued PCM");speaking.set(false);waitFor(()->!speechSession.hasUnfinishedAudio());speechSession.cancel();ok(speechEnded.await(2,TimeUnit.SECONDS),"speech cancellation failed");  System.out.println("PASS capture continues during blocked recognition; FIFO, bounded backpressure without dropping, finish drains, cancel suppresses stale results");
 }
}